import 'package:common_glasses_protocol/common_glasses_protocol.dart';
import 'package:core_ble/core_ble.dart';
import 'package:core_permission/core_permission.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../model/device_record_state.dart';

/// Device audio recording state.
final deviceRecordControllerProvider =
    NotifierProvider<DeviceRecordController, DeviceRecordState>(
  DeviceRecordController.new,
);

/// Toggles device audio recording via protocol commands.
class DeviceRecordController extends Notifier<DeviceRecordState> {
  GlassesCommandSender get _sender => ref.read(glassesCommandSenderProvider);

  @override
  DeviceRecordState build() {
    ref.listen<bool>(
      bleSessionProvider.select((session) => session.isConnected),
      (previous, connected) {
        if (previous == true && connected == false) {
          state = const DeviceRecordState();
        }
      },
    );
    return const DeviceRecordState();
  }

  /// Toggles device audio recording via protocol.
  Future<Result<void>> toggleRecording() async {
    if (!ref.read(bleSessionProvider).isConnected) {
      return const Result.failure(
        AppError(code: 'glasses.not_connected', message: 'No active connection'),
      );
    }

    final next = !state.isRecording;
    if (next) {
      final mic = ref.read(permissionServiceProvider);
      final micResult = await mic.request(AppPermission.microphone);
      final allowed = micResult.fold(
        onSuccess: (value) => value,
        onFailure: (error) {
          state = state.copyWith(lastError: error.message);
          return false;
        },
      );
      if (!allowed) {
        return const Result.failure(
          AppError(
            code: 'permission.denied',
            message: 'Microphone permission required',
          ),
        );
      }
    }

    final sendResult = await _sender.setRecording(enabled: next);
    return sendResult.fold(
      onSuccess: (_) {
        state = state.copyWith(isRecording: next, clearError: true);
        return const Result.success(null);
      },
      onFailure: (error) {
        state = state.copyWith(lastError: error.message);
        return Result.failure(error);
      },
    );
  }
}
