  /// Native `BleWatchServiceImpl.findBand()` / iOS `ble_sendFindDevice`。
  /// 无设备响应，单向发送。
  static List<int> findDevice() => [0xAB, 0x00, 0x03, 0xFF, 0x71, 0x80];

  /// Sends native connect request. Native `sendConnectRequestType(type, model)`.
  static List<int> sendConnectRequest({
    required bool reconnect,
    String model = 'Flutter',
    String uid = '0',
  }) {
    final modelBytes = utf8.encode(model).take(12).toList(growable: false);
    final uidBytes = utf8.encode(uid);
    final payload = [
      0xFF,
      0xE0,
      0x80,
      reconnect ? 0x01 : 0x00,
      modelBytes.length,
      ...modelBytes,
      uidBytes.length,
      ...uidBytes,
    ];
    return [0xAB, payload.length >> 8, payload.length & 0xFF, ...payload];
  }
