/// Sealed base type for frames received from the glasses device.
sealed class GlassesEvent {
  const GlassesEvent();
}

/// Raw, unparsed device→phone frame.
///
/// Exposes [id], [subId], and [payload] directly so downstream handlers
/// can pattern-match on specific commands without requiring this package
/// to enumerate all subIds upfront.
///
/// ponytail: typed subclasses are added here when a Feature needs them;
/// the raw fallback covers all unknowns.
class GlassesRawEvent extends GlassesEvent {
  /// Creates a raw glasses event.
  GlassesRawEvent({
    required this.id,
    required this.subId,
    required this.payload,
  }) : super();

  /// Command domain identifier (e.g. `0x34` for glasses main domain).
  final int id;

  /// Sub-command identifier.
  final int subId;

  /// Payload bytes after the frame header.
  final List<int> payload;
}

/// Live wearing-state change pushed by the device.
///
/// Native source: Android `OtherAnalyzer.wearStatus()` id=0x34 subId=0x07;
/// payload[0] = 0 (not worn) or 1 (worn).
class GlassesWearStateEvent extends GlassesEvent {
  const GlassesWearStateEvent({required this.isWorn});

  /// `true` when the device detects glasses are physically worn.
  final bool isWorn;
}

/// 设备端可同步媒体文件数量。
///
/// 原生来源：iOS `BLE_WAKEUP+Glasses.m` / Android `GlassesOrder.syncFileCount`，
/// id=0x34 subId=0x05。type: 0 全部，1 视频，2 照片，3 录音。
class GlassesMediaFileCountEvent extends GlassesEvent {
  /// 创建设备媒体文件数量事件。
  const GlassesMediaFileCountEvent({required this.type, required this.count});

  /// 文件类型：0 全部，1 视频，2 照片，3 录音。
  final int type;

  /// 设备端可同步文件数量。
  final int count;
}

/// 设备请求 App 回传经纬度。
///
/// 原生来源：iOS `BLE_WAKEUP+LatitudeLongitude.m`，id=0x3E subId=0x01。
class GlassesLocationRequestEvent extends GlassesEvent {
  /// 创建设备经纬度请求事件。
  const GlassesLocationRequestEvent();
}

/// Battery level notification pushed by the device.
///
/// Native source: Android `CommonAnalyzer` — `0xAB` frame, type byte `0x91`;
/// payload[1] = charging flag (0=no), payload[2] = battery % 0–100.
class GlassesBatteryEvent extends GlassesEvent {
  const GlassesBatteryEvent({required this.level, required this.isCharging});

  /// Battery percentage 0–100.
  final int level;

  /// Whether the device is currently charging.
  final bool isCharging;
}

/// Device platform/support info used by the native connect handshake.
///
/// Native source: Android `ConnectAnalyzer.getPairingType()` — `0xAB` frame,
/// type byte `0x20`.
class GlassesConnectPlatformEvent extends GlassesEvent {
  const GlassesConnectPlatformEvent({required this.payload});

  /// Full frame bytes for callers that need native-compatible bit checks.
  final List<int> payload;
}

/// Device BLE pairing/request status used by the native connect handshake.
///
/// Native source: Android `ConnectAnalyzer.bleRequestType()` — `0xAB` frame,
/// type byte `0x21`; byte 6 is status.
class GlassesConnectRequestEvent extends GlassesEvent {
  const GlassesConnectRequestEvent({required this.status});

  /// `0` pairing success, `2` already paired; both continue connect request.
  final int status;
}

/// Device firmware/model info reported during the connect handshake.
///
/// Native source: Android `ConnectAnalyzer.analyzeInfo()` — `0xAB` frame,
/// type byte `0x92`; bytes 6/7 = OTA version, bytes 8 or 9/10 = project code.
class GlassesDeviceInfoEvent extends GlassesEvent {
  const GlassesDeviceInfoEvent({
    required this.deviceCode,
    required this.otaVersionCode,
  });

  /// Native `DeviceInfoModel.bandVersionCode`, used as temp `DeviceModel.code`.
  final String deviceCode;

  /// Native `DeviceInfoModel.otaVersionCode`.
  final String otaVersionCode;
}

/// 设备请求 App 回传生理期月份数据。
///
/// 原生来源：Android `MenstrualAnalyzer`，legacy `0xAB/0xE7`。
class GlassesMenstrualRequestEvent extends GlassesEvent {
  /// 创建生理期数据请求事件。
  const GlassesMenstrualRequestEvent({
    required this.monthIndex,
    required this.hostCrc,
    required this.isAck,
  });

  /// 设备请求的月份下标：`0` 上月，`1` 本月，`2` 下月。
  final int monthIndex;

  /// 设备当前缓存的 CRC。
  final int hostCrc;

  /// `true` 表示设备对上次数据的校验/应答帧。
  final bool isAck;
}

/// Response to the Wi-Fi P2P open command (id=0x33 subId=0x0F).
///
/// Native source: Android `GlassesAnalyzer.handlerOpenWifiP2p`.
/// On success: [ssid] is the glasses' Wi-Fi Direct device name (Android)
/// or Wi-Fi AP SSID (iOS).
/// On failure: [success]=false, [ssid]=''.
class GlassesWifiP2pEvent extends GlassesEvent {
  const GlassesWifiP2pEvent({
    required this.success,
    required this.ssid,
    this.password = '',
  });

  /// Whether the glasses successfully opened Wi-Fi P2P / AP.
  final bool success;

  /// Wi-Fi Direct device name (Android) or AP hotspot SSID (iOS).
  /// Empty on failure.
  final String ssid;

  /// AP hotspot password (iOS AP mode only). Empty string = open network.
  /// Not used for Android Wi-Fi Direct (which uses WPS-style handshake).
  final String password;
}

/// Device-initiated simultaneous interpretation toggle command.
///
/// Native source: Android `DeviceSimInterAnalyzer` — `0xEA` frame, id=0x46 subId=0x01.
/// Glasses can start/stop interpretation independently (e.g. hardware button).
class GlassesSimInterCommandEvent extends GlassesEvent {
  const GlassesSimInterCommandEvent({
    required this.enable,
    required this.asrLanguageId,
    required this.transLanguageId,
  });

  /// `true` = start interpretation; `false` = stop.
  final bool enable;

  /// ASR source language ID as defined by the 4Paradigm language list API.
  final int asrLanguageId;

  /// Translation target language ID.
  final int transLanguageId;
}

/// Device-initiated recording control during simultaneous interpretation.
///
/// Native source: Android `DeviceSimInterAnalyzer` — `0xEA` frame, id=0x46 subId=0x04.
/// Glasses signal when their microphone starts or stops recording.
class GlassesSimInterRecordEvent extends GlassesEvent {
  const GlassesSimInterRecordEvent({required this.isRecording});

  /// `true` = glasses mic started recording; `false` = stopped.
  final bool isRecording;
}

/// 设备日程操作类型。
enum GlassesScheduleOperation {
  /// 设备同步回传的日程。
  sync(0),

  /// 新增日程。
  add(1),

  /// 修改日程。
  modify(2),

  /// 删除日程。
  delete(3);

  const GlassesScheduleOperation(this.code);

  /// 原生协议中的操作码。
  final int code;

  /// 从原生操作码创建枚举。
  static GlassesScheduleOperation? fromCode(int code) {
    return switch (code) {
      0 => sync,
      1 => add,
      2 => modify,
      3 => delete,
      _ => null,
    };
  }
}

/// 设备日程操作响应。
///
/// 原生来源：`BLE_WAKEUP+Schedule.m`，id=0x36 subId=0x01。
class GlassesScheduleOperationResultEvent extends GlassesEvent {
  /// 创建设备日程操作响应。
  const GlassesScheduleOperationResultEvent({
    required this.success,
    required this.scheduleId,
    this.resultOperation,
  });

  /// 设备是否执行成功。
  final bool success;

  /// 设备返回的日程 ID。
  final int scheduleId;

  /// 可选操作类型，部分固件会在响应尾部返回。
  final GlassesScheduleOperation? resultOperation;
}

/// 设备日程同步数量响应。
///
/// 收到该事件后，业务层应清空当前设备本地日程，再等待后续逐条日程信息。
class GlassesScheduleSyncCountEvent extends GlassesEvent {
  /// 创建设备日程同步数量响应。
  const GlassesScheduleSyncCountEvent({required this.count});

  /// 设备将回传的日程数量。
  final int count;
}

/// 设备回传的一条日程信息。
///
/// 原生来源：`BLE_WAKEUP+Schedule.m`，id=0x36 subId=0x03。
class GlassesScheduleInfoEvent extends GlassesEvent {
  /// 创建设备日程信息事件。
  const GlassesScheduleInfoEvent({
    required this.operation,
    required this.scheduleId,
    required this.startTime,
    required this.title,
  });

  /// 当前日程对应的操作类型。
  final GlassesScheduleOperation operation;

  /// 设备日程 ID。
  final int scheduleId;

  /// 秒级 Unix 时间戳。
  final int startTime;

  /// 日程标题。
  final String title;
}

/// Device wake state for the App LLM session.
///
/// Native source: iOS `WKBLELargeModelState`, Android `AppLLMAnalyzer`.
enum GlassesLlmWakeState {
  /// Device requests the App to end the current LLM session.
  end(0),

  /// Device detected the wake word and requests an LLM session.
  wake(1),

  /// Device requests interruption of the current LLM output/session.
  interrupt(2);

  const GlassesLlmWakeState(this.code);

  /// Native payload byte.
  final int code;

  static GlassesLlmWakeState? fromCode(int code) {
    return switch (code) {
      0 => end,
      1 => wake,
      2 => interrupt,
      _ => null,
    };
  }
}

/// Device requests the App to start, end, or interrupt an LLM session.
///
/// Native source: Android `AppLLMAnalyzer` — `0xEA` frame, id=0x3C subId=0x01;
/// payload[0] = 0 (end), 1 (wake), 2 (interrupt).
class GlassesLlmWakeEvent extends GlassesEvent {
  const GlassesLlmWakeEvent({required this.state});

  /// Native wake/end/interrupt state.
  final GlassesLlmWakeState state;

  /// Compatibility convenience for older call sites.
  bool get wake => state == GlassesLlmWakeState.wake;
}

/// Device signals recording state change during an LLM session.
///
/// Native source: Android `AppLLMAnalyzer` — `0xEA` frame, id=0x3C subId=0x02;
/// payload[0] = 1 (recording on) or 0 (off).
class GlassesLlmAudioControlEvent extends GlassesEvent {
  const GlassesLlmAudioControlEvent({required this.recording});

  /// `true` = device mic started recording; `false` = stopped.
  final bool recording;
}

/// Device toggles App LLM deep-thinking/search mode.
///
/// Native source: iOS `BLE_WAKEUP+LargeModel.m` id=0x3C subId=0x09;
/// payload[0] = 1 (enabled) or 0 (disabled).
class GlassesLlmDeepThinkEvent extends GlassesEvent {
  const GlassesLlmDeepThinkEvent({required this.enabled});

  /// `true` = deep thinking enabled.
  final bool enabled;
}

/// Ack/report for a device operation (photo / audio / video recording).
///
/// Native source: Android `GlassesAnalyzer.handlerDeviceOperation()` id=0x34 subId=0x11.
/// Also covers device-initiated record events on id=0x41 subId=0x01 (same payload layout).
class GlassesDeviceOperationEvent extends GlassesEvent {
  const GlassesDeviceOperationEvent({
    required this.msgType,
    required this.type,
    required this.action,
    required this.result,
    this.reason = 0,
  });

  /// 0 = command ack, 1 = unsolicited device report.
  final int msgType;

  /// 0 = photo, 1 = video, 2 = audio.
  final int type;

  /// 0 = stopped, 1 = started.
  final int action;

  /// 0 = success, 1 = failure.
  final int result;

  /// Failure reason: 0=ok, 1=fail, 2=recording, 3=videoing,
  /// 4=photoing, 5=camera not open (hall), 6=camera error.
  final int reason;

  bool get isAudio => type == 2;
  bool get isStarted => action == 1;
  bool get isSuccess => result == 0;
}

/// AIAgent OTA 升级结果事件（0x25/0x06）。
///
/// Native source: iOS `wk_analyzesisAIAgent` subId 0x06。
class GlassesOtaStatusEvent extends GlassesEvent {
  /// 创建 OTA 状态事件。
  const GlassesOtaStatusEvent({required this.success});

  /// true = 升级成功，false = 升级失败。
  final bool success;
