## 6. `device_record_fab.dart`

```dart
import 'package:common_ui/common_ui.dart';
import 'package:core_ble/core_ble.dart';
import 'package:core_theme/core_theme.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../controller/device_record_controller.dart';
import '../l10n/generated/device_record_localizations.dart';

/// Floating control to start/stop device audio recording.
class DeviceRecordFab extends ConsumerWidget {
  /// Creates the recording FAB.
  const DeviceRecordFab({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    ref.listen<String?>(
      deviceRecordControllerProvider.select((state) => state.lastError),
      (previous, error) {
        if (error != null && error != previous && context.mounted) {
          AppToast.error(context, error);
        }
      },
    );

    final l10n = DeviceRecordL10n.of(context);
    final tokens = DesignTokens.of(context);
    final isConnected = ref.watch(
      bleSessionProvider.select((state) => state.isConnected),
    );
    final isRecording = ref.watch(
      deviceRecordControllerProvider.select((state) => state.isRecording),
    );
    final controller = ref.read(deviceRecordControllerProvider.notifier);

    return FloatingActionButton.extended(
      onPressed: isConnected ? controller.toggleRecording : null,
      icon: Icon(isRecording ? Icons.stop : Icons.mic),
      label: Text(isRecording ? l10n.stopRecording : l10n.startRecording),
      backgroundColor: isRecording
          ? tokens.error.withValues(alpha: 0.12)
          : tokens.accent.withValues(alpha: 0.12),
      foregroundColor: isRecording ? tokens.error : tokens.accent,
    );
  }
}
